"""Bisect engine: resolve + confirm the range, then let a Strategy pick commits until one is confirmed.

PlainStrategy is the baseline (binary search over first-parent history, git-bisect-skip style neighbour picking).
Chunk 7's smart planner plugs in by implementing `Strategy`. Every step is bracketed by begin_step/end_step so a
crashed run resumes via `resume_investigation`; finished case runs live in the verdict cache, so a redone step
only repeats the in-flight cases.
"""
from __future__ import annotations

import os
import subprocess
from dataclasses import dataclass, field
from pathlib import Path
from typing import Protocol

from .models import BisectState, CommitResult, CulpritReport, FailureSignature, Plan
from .runner import Runner, RunnerConfig, config_from_env
from .signature import pick_primary, signatures_of
from .state import StateError, StateStore
from .tracing import step_span

COST_PER_RUN_USD = float(os.environ.get("AGENTBISECT_COST_PER_RUN", "0.002"))  # rough estimate per eval run
MULTI_REGRESSION_WARNING = "multiple regressions likely: verdicts are non-monotonic (a good commit after a bad one)"
EXIT_OK, EXIT_ERROR, EXIT_UNRESOLVED = 0, 1, 4


class BisectError(RuntimeError):
    pass


class Strategy(Protocol):
    def next_commit(self, state: BisectState) -> str | None:
        """Next sha to evaluate, or None when the search is finished."""

    def update(self, state: BisectState, sha: str, result: CommitResult) -> None:
        """Observe a verdict (state.results already contains it)."""


# -- git helpers --

def _git(repo: str, *args: str) -> str:
    p = subprocess.run(["git", "-C", repo, *args], capture_output=True, text=True)
    if p.returncode != 0:
        raise BisectError(f"git {' '.join(args)} failed: {p.stderr.strip()}")
    return p.stdout.strip()


def resolve(repo: str, rev: str) -> str:
    return _git(repo, "rev-parse", "--verify", f"{rev}^{{commit}}")


def linear_history(repo: str, good: str, bad: str) -> list[str]:
    """[good, c1, ..., bad]: first-parent chain, oldest first. Fails if good is not on bad's first-parent line."""
    chain = _git(repo, "rev-list", "--first-parent", "--reverse", f"{good}..{bad}").split()
    if not chain or chain[-1] != bad:
        raise BisectError(f"good {good[:8]} is not on the first-parent history of bad {bad[:8]}")
    return [good, *chain]


# -- narrowing (pure function of history + results; resume-safe) --

@dataclass
class Narrowing:
    lo: int  # newest known-good index below hi
    hi: int  # oldest known-bad index
    untested: list[int] = field(default_factory=list)  # indexes strictly between lo and hi with no verdict yet
    inconclusive: list[int] = field(default_factory=list)  # strictly between: skip / flaky
    non_monotonic: bool = False

    @property
    def done(self) -> bool:
        return not self.untested

    @property
    def culprit(self) -> int | None:
        """Index of the culprit when the search converged on a single commit."""
        return self.hi if self.done and self.hi - self.lo == 1 else None


def narrow(history: list[str], results: dict[str, CommitResult]) -> Narrowing:
    def v(i: int) -> str | None:
        r = results.get(history[i])
        return r.verdict if r else None

    bad = [i for i in range(len(history)) if v(i) == "bad"]
    good = [i for i in range(len(history)) if v(i) == "good"]
    hi = min(bad) if bad else len(history) - 1
    lo = max([i for i in good if i < hi], default=0)
    non_mono = any(g > b for b in bad for g in good)
    between = range(lo + 1, hi)
    return Narrowing(lo, hi, [i for i in between if v(i) is None],
                     [i for i in between if v(i) in ("skip", "flaky")], non_mono)


class PlainStrategy:
    """Binary search; if the midpoint is skip/flaky-inconclusive it is already in `results`, so the nearest
    untested neighbour is taken instead (alternating sides), like `git bisect skip`."""
    name = "plain"

    def __init__(self, history: list[str]):
        self.history = history

    def next_commit(self, state: BisectState) -> str | None:
        n = narrow(self.history, state.results)
        if not n.untested:
            return None
        mid = (n.lo + n.hi) / 2
        return self.history[min(n.untested, key=lambda i: (abs(i - mid), i))]

    def update(self, state: BisectState, sha: str, result: CommitResult) -> None:
        pass


# -- engine --

@dataclass
class Outcome:
    kind: str  # culprit | unresolved | failed
    sha: str | None = None
    candidates: list[str] = field(default_factory=list)
    message: str = ""


def make_runner(store: StateStore, st: BisectState) -> Runner:
    if not st.spec or not st.spec.cases:
        raise BisectError("investigation has no eval cases (run intake first)")
    judged = tuple((st.spec.predicate or {}).get("rubric") or ())  # cases with a judge rubric
    return Runner(st.repo, config_from_env(list(st.spec.cases), judge_cases=judged), store.cache(st.repo),
                  signature=st.spec.signature)


def _account(st: BisectState, delta: int) -> None:
    m = st.metrics
    m["eval_rounds"] = m.get("eval_rounds", 0) + delta
    m["cost_usd"] = round(m["eval_rounds"] * COST_PER_RUN_USD, 4)


def _discover_signature(store: StateStore, st: BisectState, runner: Runner, bad: str) -> None:
    """Pick the failing check to bisect on, once: evaluate the bad end over the whole suite, group every failing
    check into signatures (all kept in metrics["signatures"]) and bisect the one that fires in the bad trace's
    case. Skipped when intake already supplied a signature or it was discovered before (resume-safe)."""
    if not st.spec or st.spec.signature is not None or st.metrics.get("signatures_discovered"):
        runner.signature = st.spec.signature if st.spec else None
        return
    step = store.begin_step(st, "signature_discovery", sha=bad)
    before = runner.eval_rounds
    runner.signature = None
    with step_span("signature_discovery", sha=bad, step=step):
        res = runner.evaluate_commit(bad, f"{st.id}-s{step}", list(st.spec.cases))
    _account(st, runner.eval_rounds - before)
    sigs = signatures_of(res)
    # A check that failed in a single run is as likely sampling noise as a regression (one flaky run can fail
    # several checks at once): run those cases once more and keep only what reproduces.
    weak = [s for s in sigs if s.fails < 2]
    if weak:
        redo = sorted({c for s in weak for c in s.cases})
        saved, runner.cfg.repeats = runner.cfg.repeats, max(runner.cfg.repeats, 2)
        before = runner.eval_rounds
        try:
            with step_span("signature_confirm", sha=bad, step=step):
                res = runner.evaluate_commit(bad, f"{st.id}-s{step}c", redo)
        finally:
            runner.cfg.repeats = saved
        _account(st, runner.eval_rounds - before)
        everything = sorted((FailureSignature.from_dict(d) for d in runner.signatures_at(bad, list(st.spec.cases))),
                            key=lambda x: (-x.fails, x.key))
        sigs = [x for x in everything if x.fails >= 2]
        st.metrics["signatures_unconfirmed"] = [x.to_dict() for x in everything if x not in sigs]
    st.metrics["signatures_discovered"] = True
    st.metrics["signatures"] = [s.to_dict() for s in sigs]
    st.spec.signature = runner.signature = pick_primary(sigs, st.spec.bad_case)
    if st.spec.signature and st.spec.bad_case and st.spec.bad_case not in st.spec.signature.cases:
        st.metrics.setdefault("warnings", []).append(
            f"no reproducible failing check in the bad trace's case {st.spec.bad_case}: bisecting "
            f"{st.spec.signature.key} from other cases")
    if st.spec.signature is None:
        st.metrics.setdefault("warnings", []).append(
            "no failing check found at the bad end: bisecting on whole-case pass rate")
    store.end_step(st)


def _evaluate(store: StateStore, st: BisectState, runner: Runner, sha: str, kind: str) -> CommitResult:
    step = store.begin_step(st, kind, sha=sha)
    before = runner.eval_rounds
    with step_span("bisect_step", sha=sha, step=step, kind=kind):
        res = runner.evaluate_commit(sha, f"{st.id}-s{step}")
    m = st.metrics
    _account(st, runner.eval_rounds - before)
    m["commits_evaluated"] = m.get("commits_evaluated", 0) + (0 if res.from_cache else 1)
    m["cache_hits"] = m.get("cache_hits", 0) + (1 if res.from_cache else 0)
    store.end_step(st, sha, res)
    return res


def _fail(store: StateStore, st: BisectState, msg: str) -> Outcome:
    store.set_status(st, "failed", error=msg)
    return Outcome("failed", message=msg)


def _confirm_ends(store: StateStore, st: BisectState, runner: Runner, good: str, bad: str) -> str | None:
    """Re-run both ends once (cached verdicts count). Returns an error message or None."""
    for sha, want, label in ((bad, "bad", "bad end"), (good, "good", "good end")):
        res = st.results.get(sha)
        if res is None or res.verdict == "skip":
            res = _evaluate(store, st, runner, sha, f"confirm_{want}")
        if res.verdict != want:
            if want == "bad" and res.verdict == "good":
                sig = f" for signature {st.spec.signature.key}" if st.spec and st.spec.signature else ""
                return f"bad end does not reproduce{sig}: {sha[:8]} passes (pass_rate {res.pass_rate:.2f})"
            if want == "good" and res.verdict == "bad":
                return f"good end is not good: {sha[:8]} fails (pass_rate {res.pass_rate:.2f})"
            return f"{label} {sha[:8]} is unusable: verdict {res.verdict} ({res.reason})"
    return None


def _confidence(history: list[str], st: BisectState, n: Narrowing) -> tuple[str, dict]:
    lo_r, hi_r = st.results[history[n.lo]], st.results[history[n.hi]]
    band = {"good_pass_rate": lo_r.pass_rate, "bad_pass_rate": hi_r.pass_rate}
    inconclusive = [h for h in history if (r := st.results.get(h)) and r.verdict in ("skip", "flaky")]
    if n.non_monotonic:
        return "low", band
    if inconclusive or lo_r.pass_rate is None or hi_r.pass_rate is None:
        return "medium", band
    clear = lo_r.pass_rate >= 0.95 and hi_r.pass_rate <= 0.4
    return ("high" if clear else "medium"), band


def run_investigation(store: StateStore, st: BisectState, runner: Runner | None = None,
                      strategy: Strategy | None = None) -> Outcome:
    if st.status == "created":
        store.set_status(st, "running")
    elif st.status != "running":
        raise StateError(f"cannot run an investigation in status '{st.status}'")
    try:
        runner = runner or make_runner(store, st)
        bad = resolve(st.repo, st.bad_sha or "HEAD")
        if not st.good_sha:
            return _fail(store, st, "no good commit known: pass --good <sha>")
        good = resolve(st.repo, st.good_sha)
        st.good_sha, st.bad_sha = good, bad
        if good == bad:
            return _fail(store, st, "good and bad are the same commit")
        history = linear_history(st.repo, good, bad)
        if st.plan is None:
            st.plan = Plan(mode="plain")
        st.metrics.setdefault("strategy", getattr(strategy, "name", "plain"))
        strategy = strategy or PlainStrategy(history)
        store.save(st)

        _discover_signature(store, st, runner, bad)
        err = _confirm_ends(store, st, runner, good, bad)
        if err:
            return _fail(store, st, err)
        while True:
            sha = strategy.next_commit(st)
            if sha is None:
                break
            strategy.update(st, sha, _evaluate(store, st, runner, sha, "bisect"))
        _monotonic_probe(store, st, runner, history)
        return _conclude(store, st, history)
    except (BisectError, StateError) as e:
        return _fail(store, st, str(e))
    except Exception as e:  # infra/pin errors: keep in_flight so `resume` redoes the step
        st.status, st.error = "failed", f"{type(e).__name__}: {e}"
        store.save(st)
        return Outcome("failed", message=st.error)


def _monotonic_probe(store: StateStore, st: BisectState, runner: Runner, history: list[str]) -> None:
    """One extra evaluation between the culprit and the bad end: if it is good, the regression is not a clean step
    (good after bad), which _conclude flags as multiple regressions. Skipped when no commit lies between."""
    n = narrow(history, st.results)
    if n.culprit is None:
        return
    i = (n.hi + len(history) - 1) // 2
    if n.hi < i < len(history) - 1 and history[i] not in st.results:
        _evaluate(store, st, runner, history[i], "monotonic_probe")


def _conclude(store: StateStore, st: BisectState, history: list[str]) -> Outcome:
    n = narrow(history, st.results)
    warnings = st.metrics.setdefault("warnings", [])
    if n.non_monotonic and MULTI_REGRESSION_WARNING not in warnings:
        warnings.append(MULTI_REGRESSION_WARNING)
    if n.culprit is None:
        cands = [history[i] for i in range(n.lo + 1, n.hi + 1)]
        st.metrics["ambiguous"] = cands
        msg = (f"culprit is within these skipped/flaky commits (cannot be narrowed): "
               f"{', '.join(c[:8] for c in cands)}")
        st.status, st.error = "failed", msg  # needs a human; resume allowed
        store.save(st)
        return Outcome("unresolved", candidates=cands, message=msg)
    conf, band = _confidence(history, st, n)
    st.metrics["confidence_band"] = band
    st.metrics.pop("ambiguous", None)
    sha = history[n.hi]
    if not (st.culprit and st.culprit.sha == sha):  # a resumed run keeps its analysis / revert test
        st.culprit = CulpritReport(sha=sha, confidence=conf)
    store.set_status(st, "culprit_found")
    return Outcome("culprit", sha=sha, message=f"culprit {sha[:8]} (confidence {conf})")


def report(st: BisectState, out: Outcome) -> str:
    m = st.metrics
    lines = [f"[{st.id}] {out.message}" if out.message else f"[{st.id}] {out.kind}"]
    for w in m.get("warnings", []):
        lines.append(f"  WARNING: {w}")
    if st.spec and st.spec.signature:
        lines.append(f"  bisected on failure signature: {st.spec.signature.label} "
                     f"(cases: {', '.join(st.spec.signature.cases) or 'all'})")
    lines.append(f"  strategy={m.get('strategy', 'plain')} steps={st.step} eval_rounds={m.get('eval_rounds', 0)} "
                 f"cost~${m.get('cost_usd', 0.0)} cache_hits={m.get('cache_hits', 0)}")
    return "\n".join(lines)


def resume_investigation(store: StateStore, st: BisectState, runner: Runner | None = None,
                         strategy: Strategy | None = None) -> int:
    """Entry point used by `agentbisect resume`; also the tail of `investigate --strategy`. Exit code."""
    out = run_investigation(store, st, runner, strategy)
    print(report(st, out))
    return {"culprit": EXIT_OK, "unresolved": EXIT_UNRESOLVED}.get(out.kind, EXIT_ERROR)

    return "\n".join(lines)


def _add_intake_args(p: argparse.ArgumentParser) -> None:
    g = p.add_mutually_exclusive_group(required=True)
    g.add_argument("--trace", help="neatlogs trace id of a bad run")
    g.add_argument("--detection", help="neatlogs detection id")
    g.add_argument("--issue", help="GitHub issue URL (read with `gh issue view`)")
    p.add_argument("--repo", required=True, help="path to the target repo (has evals/cases.jsonl)")
    p.add_argument("--fixtures", help="recorded JSON trace fixtures instead of the live neatlogs CLI")
    p.add_argument("--project", help="neatlogs project uuid (default $NEATLOGS_PROJECT_ID)")
    p.add_argument("--workflow", default="support-agent", help="neatlogs workflow name of the target's runs")
    p.add_argument("--strategy", choices=["smart", "plain"], default="smart",
                   help="bisect strategy run after intake (default smart: rank commits by trace divergence, "
                        "code impact and checkpoint intent, then fall back to plain)")
    p.add_argument("--llm-proxy", default="off", metavar="auto|URL|off",
                   help="route the target's Anthropic calls through the local `claude`-CLI proxy: auto = start one "
                        "for this run, URL = use a running one, off (default) = use the real API key")
    p.add_argument("--signature", metavar="KEY",
                   help="bisect this failing check only (e.g. call_args:issue_refund.amount); default: discovered "
                        "from the bad end's eval results")
    p.add_argument("--all-signatures", action=argparse.BooleanOptionalAction, default=None,
                   help="bisect every distinct failing check at the bad end separately (one culprit per failure "
                        "signature). Default: on when several are found")
    p.add_argument("--all-categories", action="store_true",
                   help="build the suite from every category's non-held-out cases instead of the bad trace's "
                        "category only, so regressions in other features surface as their own signatures")
    p.add_argument("--intake-only", action="store_true", help="stop after intake; do not run the bisect")
    p.add_argument("--good", help="known-good commit (overrides the one intake found)")
    p.add_argument("--bad", help="known-bad commit (default: failing trace's commit, else HEAD)")


def trace_source(a: argparse.Namespace | None = None, meta: dict | None = None):
    """Trace source for span divergence; `meta` ({fixtures, project}) comes from a saved investigation."""
    fixtures = getattr(a, "fixtures", None) if a else (meta or {}).get("fixtures")
    project = getattr(a, "project", None) if a else (meta or {}).get("project")
    return FixtureSource(fixtures) if fixtures else NeatlogsCliSource(project=project)


def make_strategy(st: BisectState, store: StateStore, meta: dict | None = None):
    """Strategy for an investigation: None means the engine default (plain)."""
    if st.metrics.get("strategy", "plain") != "smart":
        return None
    from .planner import Planner, SmartStrategy
    try:
        source = trace_source(meta=meta)
    except Exception:  # no usable trace source: the planner ranks by checkpoint intent alone
        source = None
    return SmartStrategy(Planner(st.repo, source=source), store)


def run_intake(a: argparse.Namespace) -> IntakeResult:
    if a.issue:
        return intake_issue(a.issue, a.repo)
    src = FixtureSource(a.fixtures) if a.fixtures else NeatlogsCliSource(project=a.project)
    if a.trace:
        return intake_trace(src, a.trace, a.repo, workflow=a.workflow,
                            all_categories=getattr(a, "all_categories", False))
    return intake_detection(src, a.detection, a.repo, workflow=a.workflow,
                            all_categories=getattr(a, "all_categories", False))


def _parser() -> argparse.ArgumentParser:
    p = argparse.ArgumentParser(prog="agentbisect", description="git bisect for agent behavior")
    p.add_argument("--state-dir", default=DEFAULT_DIR, help=f"state directory (default {DEFAULT_DIR})")
    sub = p.add_subparsers(dest="cmd", required=True)
    inv = sub.add_parser("investigate", help="run intake and record the RegressionSpec in a new investigation")
    _add_intake_args(inv)
    _add_intake_args(sub.add_parser("intake", help="run intake and print the RegressionSpec (no state written)"))
    c = sub.add_parser("compare", help="run plain and smart bisect on one investigation (separate empty caches) "
                                       "and print eval rounds and cost")
    c.add_argument("id")
    c.add_argument("--fixtures", help="recorded trace fixtures for the smart planner's span divergence")
    c.add_argument("--project", help="neatlogs project uuid")
    rp = sub.add_parser("report", help="write the Markdown/HTML report; optionally open a PR (dry-run by default)")
    rp.add_argument("id")
    rp.add_argument("--format", choices=["md", "html", "both"], default="both")
    rp.add_argument("--out", help="output directory (default: evidence/ in the agentbisect repo)")
    rp.add_argument("--open-pr", action="store_true", help="prepare a PR from the best fix branch (dry-run)")
    rp.add_argument("--confirm-open-pr", action="store_true",
                    help="really `git push` and `gh pr create` (requires --open-pr)")
    rp.add_argument("--draft", action="store_true", help="force a draft PR (default: draft iff the fix is unverified)")
    lp = sub.add_parser("llm-proxy", help="serve an Anthropic-compatible API backed by your logged-in `claude` CLI")
    lp.add_argument("--port", type=int, default=8787)
    lp.add_argument("--concurrency", type=int, default=None,
                    help="max model calls in flight (default $AGENTBISECT_MODEL_CONCURRENCY or 4)")
    lp.add_argument("--cache", action="store_true", help="cache responses in .agentbisect/llm_cache")
    lp.add_argument("--cache-dir")
    lp.add_argument("--debug-dump", metavar="DIR", help="DEBUG: write every rendered prompt + output to DIR (use /tmp)")
    js = sub.add_parser("judge-smoke", help="one Sonnet judge call through the proxy; prints the model recorded")
    js.add_argument("--proxy-url", help="running llm-proxy (default: start a throwaway one on your claude login)")
    sub.add_parser("watch", help="poll neatlogs detections and auto-investigate (not implemented yet)")
    r = sub.add_parser("resume", help="resume an interrupted investigation")
    r.add_argument("id")
    s = sub.add_parser("status", help="show investigations")
    s.add_argument("id", nargs="?")
    return p


def main(argv: list[str] | None = None) -> int:
    a = _parser().parse_args(argv)
    store = StateStore(a.state_dir)
    if a.cmd == "llm-proxy":
        from .llm_proxy import run_forever
        return run_forever(a.port, a.concurrency, a.cache, a.cache_dir, debug_dump=a.debug_dump)
    if a.cmd == "judge-smoke":
        from .llm_proxy import judge_smoke
        try:
            r = judge_smoke(a.proxy_url)
        except Exception as e:
            print(f"judge-smoke failed: {type(e).__name__}: {e}", file=sys.stderr)
            return 1
        print(json.dumps(r, indent=2))
        return 0 if r["match"] else 1
    if a.cmd == "investigate":
        with _llm_proxy(getattr(a, "llm_proxy", "off")):
            return _main(a, store)
    return _main(a, store)


@contextlib.contextmanager
def _llm_proxy(mode: str):
    """`auto` starts an in-process proxy for the duration; a URL is used as is. Runners read the env var."""
    px = None
    prev = os.environ.get("AGENTBISECT_LLM_PROXY_URL")
    if mode == "auto":
        from .llm_proxy import LLMProxy
        px = LLMProxy(cache_dir=".agentbisect/llm_cache")
        px.serve(0)
        os.environ["AGENTBISECT_LLM_PROXY_URL"] = px.url
        print(f"llm proxy (own claude login) at {px.url}", file=sys.stderr)
    elif mode and mode != "off":
        os.environ["AGENTBISECT_LLM_PROXY_URL"] = mode
    try:
        yield
    finally:
        if px:
            print(f"llm proxy stats: {json.dumps(px.stats.snapshot())}", file=sys.stderr)
            px.stop()
        if prev is None:
            os.environ.pop("AGENTBISECT_LLM_PROXY_URL", None)
        else:
            os.environ["AGENTBISECT_LLM_PROXY_URL"] = prev


def _main(a: argparse.Namespace, store: StateStore) -> int:
    if a.cmd in ("investigate", "intake"):
        try:
            res = run_intake(a)
        except WaitingOnHumanLogin as e:
            print(f"error: {e}", file=sys.stderr)
            return 3
        except IntakeError as e:
            print(f"error: {e}", file=sys.stderr)
            return 1
        if a.cmd == "intake":
            print(json.dumps(res.to_dict(), indent=2))
            return 0
        st = store.create(a.repo, spec=res.spec, good_sha=res.good_sha, bad_sha=res.bad_sha)
        print(f"investigation {st.id} created (status={st.status}); spec: {len(res.spec.cases)} cases, "
              f"{len(res.spec.held_out)} held out, {len(res.spec.good_trace_ids)} good traces, "
              f"range good={res.good_sha or '?'} bad={res.bad_sha or '?'}")
        for n in res.notes:
            print(f"  - {n}")
        if a.good:
            st.good_sha = a.good
        if a.bad:
            st.bad_sha = a.bad
        store.save(st)
        meta = {"fixtures": a.fixtures, "project": a.project}
        st.metrics["strategy"] = a.strategy
        st.metrics["source"] = meta
        store.save(st)
        if a.intake_only:
            print("intake only; run `agentbisect resume " + st.id + "` to bisect")
            return 0
        if a.signature:
            from .signature import signature_from_key
            st.spec.signature = signature_from_key(a.signature)
            store.save(st)
        code = _run_one(store, st, meta)
        if a.all_signatures is not False:  # several failing checks at the bad end => one investigation each
            from .signature import spawn_siblings
            for sib in spawn_siblings(store, st):
                print(f"\nsibling investigation {sib.id} for failure signature {sib.spec.signature.label}")
                sib_code = _run_one(store, sib, meta)  # always run every sibling, even if the primary failed
                code = code or sib_code
        return code
    if a.cmd == "watch":
        print("agentbisect watch: not implemented yet (later chunk)", file=sys.stderr)
        return 2
    try:
        if a.cmd == "compare":
            return _compare(a, store)
        if a.cmd == "report":
            return _report(a, store)
        if a.cmd == "status":
            states = [store.load(a.id)] if a.id else store.list()
            if not states:
                print("no investigations")
            for st in states:
                print(_summary(st))
            return 0
        st = store.load(a.id)
        redo = store.resume(st)
        print(f"resumed {st.id}" + (f"; will redo interrupted step: {redo}" if redo else ""))
        return _run_one(store, st, st.metrics.get("source"))
    except StateError as e:
        print(f"error: {e}", file=sys.stderr)
        return 1


def _proxy_events() -> dict | None:
    url = os.environ.get("AGENTBISECT_LLM_PROXY_URL")
    if not url:
        return None
    import urllib.request
    try:
        with urllib.request.urlopen(url.rstrip("/") + "/events", timeout=5) as f:
            return json.loads(f.read())
    except Exception:
        return None


def record_throttle(store: StateStore, st: BisectState, mark: dict | None) -> None:
    """Add what the LLM proxy logged since `mark` (a /events snapshot taken before the run) to
    metrics["throttle"], so a report can cite backoffs and recoveries as evidence. Counts are deltas, so
    siblings sharing a proxy and resumed runs neither double count nor lose earlier counts. No-op without a proxy."""
    now = _proxy_events()
    if not mark or not now or "totals" not in now or "totals" not in mark:
        return
    d = {k: now["totals"][k] - mark["totals"][k] for k in now["totals"]}
    if not any(d.values()):
        return
    t = st.metrics.setdefault("throttle", {"backoffs": 0, "recovered": 0, "gave_up": 0, "waited_s": 0.0, "events": []})
    t["backoffs"] += d["backoff"]
    t["recovered"] += d["recovered"]
    t["gave_up"] += d["gave_up"]
    t["waited_s"] = round(t["waited_s"] + d["waited_s"], 1)
    t["concurrency"] = now.get("concurrency")
    t["events"] = (t["events"] + [e for e in now.get("events", []) if e.get("seq", 0) >= mark["next_seq"]])[-50:]
    try:
        store.save(st)
    except OSError:
        pass


def _run_one(store: StateStore, st: BisectState, meta: dict | None) -> int:
    from .bisect import resume_investigation
    init_tracing(st.id)
    mark = _proxy_events()
    try:
        return _explain(store, st, int(resume_investigation(store, st, strategy=make_strategy(st, store, meta))), meta)
    finally:
        record_throttle(store, st, mark)
        shutdown_tracing()


def _explain(store: StateStore, st: BisectState, code: int, meta: dict | None) -> int:
    """After a bisect that found a culprit: culprit analysis, then the revert test (both resume-safe)."""
    if code != 0 or st.status != "culprit_found" or not st.culprit:
        return code
    from .verify import confirm_culprit
    try:
        source = trace_source(meta=meta)
    except Exception:
        source = None
    try:
        confirm_culprit(store, st, source=source)
    except Exception as e:  # keep the culprit; `resume` redoes the interrupted step
        print(f"error during culprit analysis / revert test: {type(e).__name__}: {e}", file=sys.stderr)
        return 1
    print("\n".join(describe_revert(st)))
    return 0


def _compare(a: argparse.Namespace, store: StateStore) -> int:
    from .bisect import make_runner
    from .planner import Planner, SmartStrategy, compare_strategies, format_comparison
    st = store.load(a.id)
    meta = {"fixtures": a.fixtures, "project": a.project}

    def strategies(name: str, s: StateStore):
        if name == "plain":
            return None
        return SmartStrategy(Planner(st.repo, source=trace_source(meta=meta)), s)

    res = compare_strategies(st, str(store.base), make_runner, strategies)
    print(format_comparison(res))
    st.metrics["comparison"] = res
    store.save(st)
    return 0


def _report(a: argparse.Namespace, store: StateStore) -> int:
    from .report import open_pr, write_reports
    if a.confirm_open_pr and not a.open_pr:
        print("error: --confirm-open-pr requires --open-pr", file=sys.stderr)
        return 2
    st = store.load(a.id)
    for p in write_reports(st, a.out, a.format):
        print(f"wrote {p}")
    if a.open_pr:
        try:
            open_pr(st, st.repo, draft=True if a.draft else None, confirm=a.confirm_open_pr)
        except (ValueError, RuntimeError) as e:
            print(f"error: {e}", file=sys.stderr)
            return 1
        if a.confirm_open_pr and st.status in ("verifying", "fixing", "culprit_found"):
            store.set_status(st, "reported")
    return 0

"""Reporter: Markdown + self-contained HTML report from a saved state file, and a gated `gh pr create`.

Both renderers work from one dict built by `build_report` so they always agree. Every string from the repo
(commit messages, intents, diffs) is untrusted: the HTML path escapes everything, the Markdown path puts it in
fences that cannot be closed from inside.

PR opening is DRY-RUN unless `confirm=True` (CLI: `--open-pr --confirm-open-pr`); only then do `git push` and
`gh pr create` run.
"""
from __future__ import annotations

import html
import os
import re
import subprocess
from pathlib import Path
from typing import Any, Callable

from .models import BisectState, FixAttempt

PR_FOOTER = "🤖 Generated with [Claude Code](https://claude.com/claude-code)"
# Dashboard link pattern is UNVERIFIED (the docs only give the host https://app.neatlogs.com); override with
# AGENTBISECT_NEATLOGS_TRACE_URL. Trace ids are always printed next to any link.
DEFAULT_TRACE_URL = "https://app.neatlogs.com/traces/{trace_id}"
MULTI_REGRESSION = "multiple regressions likely"
SCORE_TOLERANCE = 0.1  # same slack the revert test uses against the good commit's pass rate
EVIDENCE_DIR = Path(__file__).resolve().parent.parent / "evidence"


def trace_url(trace_id: str) -> str:
    tpl = os.environ.get("AGENTBISECT_NEATLOGS_TRACE_URL", DEFAULT_TRACE_URL)
    return tpl.replace("{project}", os.environ.get("NEATLOGS_PROJECT_ID", "")).replace("{trace_id}", trace_id)


def checkpoint_id(repo: str, ref: str) -> str | None:
    """Entire-Checkpoint trailer of a commit/branch, best effort (None when absent or git fails)."""
    try:
        out = subprocess.run(["git", "-C", repo, "log", "-1", "--format=%(trailers:key=Entire-Checkpoint,valueonly)",
                              ref], capture_output=True, text=True, timeout=20)
    except (OSError, subprocess.SubprocessError):
        return None
    v = out.stdout.strip().splitlines()
    return v[0].strip() if out.returncode == 0 and v and v[0].strip() else None


def _fmt(x: Any, pct: bool = True) -> str:
    if x is None:
        return "n/a"
    return f"{x * 100:.0f}%" if pct and isinstance(x, (int, float)) else str(x)


def fix_passes(a: FixAttempt, baseline: float | None) -> bool:
    ok_score = lambda s: s is not None and (baseline is None or s >= baseline - SCORE_TOLERANCE)  # noqa: E731
    return bool(a.intent_test_passed) and ok_score(a.eval_score) and ok_score(a.held_out_score)


def best_attempt(st: BisectState, baseline: float | None) -> FixAttempt | None:
    """First attempt that passes, else the closest one (highest held-out then eval score), else None."""
    if not st.fix_attempts:
        return None
    for a in st.fix_attempts:
        if fix_passes(a, baseline):
            return a
    return max(st.fix_attempts, key=lambda a: ((a.held_out_score or 0) + (a.eval_score or 0), a.attempt))


def build_report(st: BisectState, repo: str | None = None) -> dict[str, Any]:
    repo = repo or st.repo
    c, m = st.culprit, st.metrics
    rt = m.get("revert_test") or {}
    baseline = rt.get("baseline_pass_rate")
    if baseline is None and st.good_sha in st.results:
        baseline = st.results[st.good_sha].pass_rate
    before = rt.get("culprit_pass_rate")
    if before is None and c and c.sha in st.results:
        before = st.results[c.sha].pass_rate
    flags = list(dict.fromkeys([*(c.flags if c else []), *m.get("warnings", [])]))
    attempt = best_attempt(st, baseline)
    fix: dict[str, Any] | None = None
    if attempt:
        fix = {"branch": attempt.branch, "attempt": attempt.attempt, "attempts": len(st.fix_attempts),
               "before": before, "after": attempt.eval_score, "baseline": baseline,
               "held_out": attempt.held_out_score, "intent_test": attempt.intent_test_passed,
               "passed": fix_passes(attempt, baseline), "trace_ids": list(attempt.trace_ids), "diff": attempt.diff,
               "checkpoint": checkpoint_id(repo, attempt.branch) if repo else None}
    traces: list[tuple[str, str]] = []
    if st.spec and st.spec.bad_trace_id:
        traces.append(("failing trace", st.spec.bad_trace_id))
    traces += [("passing trace (earlier)", t) for t in (st.spec.good_trace_ids if st.spec else [])]
    if c:
        traces += [("eval run at culprit", t) for t in (st.results.get(c.sha).trace_ids if c.sha in st.results else [])]
    if fix:
        traces += [(f"fix attempt {fix['attempt']}", t) for t in fix["trace_ids"]]
    cmp_ = m.get("comparison")
    rounds = None
    if cmp_ and "plain" in cmp_ and "smart" in cmp_:
        rounds = {"plain": cmp_["plain"], "smart": cmp_["smart"], "saved": cmp_.get("saved_rounds")}
    elif m.get("eval_rounds") is not None:
        rounds = {m.get("strategy", "?"): {"eval_rounds": m.get("eval_rounds"), "cost_usd": m.get("cost_usd")}}
    sig = st.spec.signature if st.spec else None
    others = [d for d in m.get("signatures", []) if not sig or d.get("key") != sig.key]
    signature = {"label": sig.label, "key": sig.key, "cases": list(sig.cases), "others": others,
                 "siblings": list(m.get("signature_siblings", [])),
                 "group": m.get("signature_group")} if sig else None
    th = m.get("throttle") or {}
    throttle = (f"Model throttling: {th['backoffs']} backoff(s) totalling {th['waited_s']}s (exponential with jitter, "
                f"concurrency {th.get('concurrency')}); {th['recovered']} call(s) recovered, {th['gave_up']} gave up."
                ) if th.get("backoffs") else None
    return {
        "throttle": throttle, "signature": signature, "id": st.id, "repo": repo, "status": st.status, "good_sha": st.good_sha, "bad_sha": st.bad_sha,
        "culprit": c, "flags": flags, "multi": any(MULTI_REGRESSION in f for f in flags),
        "low_conf": bool(c and c.confidence == "low"),
        "revert": {"passed": c.revert_test_passed if c else None, "baseline": baseline, "culprit_rate": before,
                   "reverted": rt.get("reverted_pass_rate"), "ran": "revert_test" in m},
        "fix": fix, "rounds": rounds, "metrics": m,
        "steps": st.context_tokens_per_step,
        "commits": [{"sha": s, "verdict": r.verdict, "pass_rate": r.pass_rate, "repeats": r.repeats,
                     "runs": len(r.trace_ids), "cached": r.from_cache, "reason": r.reason}
                    for s, r in st.results.items()],
        "traces": traces,
        "culprit_checkpoint": checkpoint_id(repo, c.sha) if (c and repo) else None,
        "intent_labelled": c.intent_source == "checkpoint" if c else False,
    }


# ----------------------------------------------------------------------------------------------- Markdown

def _fence(text: str, lang: str = "") -> str:
    n = max([3] + [len(x) + 1 for x in re.findall(r"`+", text)])
    f = "`" * n
    return f"{f}{lang}\n{text.rstrip()}\n{f}"


def _md_cell(s: Any) -> str:
    return str(s).replace("|", "\\|").replace("\n", " ")


def _intent_label(r: dict[str, Any]) -> str:
    c = r["culprit"]
    if c and c.intent_source == "checkpoint":
        return "Original intent (from the Entire checkpoint of the commit; the coding agent's own prompt and reasoning)"
    return "Original intent (NO CHECKPOINT: reconstructed from the commit message only)"


def _signature_lines(r: dict[str, Any]) -> list[str]:
    sg = r.get("signature")
    if not sg:
        return []
    out = [f"Bisected on the failure signature `{sg['label']}` (key `{sg['key']}`; cases "
           f"{', '.join(sg['cases']) or 'all'}). A commit is bad only if THIS check fails; other failures count as "
           "a pass for this signature. AgentBisect separates overlapping regressions by failure signature."]
    if sg["others"]:
        out.append("Other failing checks at the bad end (separate signatures, each bisected on its own): "
                   + "; ".join(f"{d['key']} (cases {', '.join(d.get('cases', []))})" for d in sg["others"]))
    if sg["siblings"]:
        out.append("Sibling investigations: " + "; ".join(
            f"{x.get('id')} [{x.get('key')}] culprit {(x.get('culprit') or 'none')[:10]}" for x in sg["siblings"]))
    return out


def _signature_md(r: dict[str, Any]) -> list[str]:
    lines = _signature_lines(r)
    return ["## Failure signature", "", *[y for x in lines for y in (x, "")]] if lines else []


def render_markdown(r: dict[str, Any], pr: bool = False) -> str:
    c, fx = r["culprit"], r["fix"]
    L: list[str] = [f"# AgentBisect report: {c.sha[:10] if c else 'no culprit found'}", "",
                    f"Investigation `{r['id']}` - status `{r['status']}` - range `{(r['good_sha'] or '?')[:10]}`.."
                    f"`{(r['bad_sha'] or '?')[:10]}`", ""]
    if not c:
        L += ["No culprit was identified yet.", ""]
        return "\n".join(L) + "\n"
    L += [f"**Confidence: {c.confidence or 'unknown'}**", ""]
    if r["multi"] or r["low_conf"]:
        L += ["> **Warning: multiple regressions likely.** Verdicts conflict or the revert did not clear the "
              "regression, so this commit may be only one of several causes." if r["multi"] else
              "> **Warning: low confidence.** Treat this culprit as a lead, not a proof.", ""]
    other = [f for f in r["flags"] if MULTI_REGRESSION not in f]
    if other:
        L += ["Flags: " + "; ".join(other), ""]
    L += _signature_md(r)
    if r.get("throttle"):
        L += [r["throttle"], ""]
    L += ["## Culprit commit", "", f"`{c.sha}`", ""]
    if r["culprit_checkpoint"]:
        L += [f"Entire checkpoint: `{r['culprit_checkpoint']}`", ""]
    L += [f"## {_intent_label(r)}", "", _fence(c.checkpoint_intent or "(none recorded)", "text"), ""]
    L += ["## Semantic diff and impacted symbols", "", _fence(c.semantic_diff or "(none recorded)", "text"), ""]
    L += ["Impacted symbols: " + (", ".join(f"`{s}`" for s in c.impacted_symbols) or "none found"), ""]
